/* eslint-disable max-len, max-statements */

'use strict';

// MODULES //

var typedarray2json = require( '@stdlib/array/to-json' );
var Uint32Array = require( '@stdlib/array/uint32' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isBoolean = require( '@stdlib/assert/is-boolean' ).isPrimitive;
var isCollection = require( '@stdlib/assert/is-collection' );
var isNonNegativeInteger = require( '@stdlib/assert/is-nonnegative-integer' ).isPrimitive;
var isObject = require( '@stdlib/assert/is-plain-object' );
var isUint32Array = require( '@stdlib/assert/is-uint32array' );
var gcopy = require( '@stdlib/blas/base/gcopy' );
var UINT32_MAX = require( '@stdlib/constants/uint32/max' );
var rotr = require( '@stdlib/number/uint32/base/rotr' );
var add = require( '@stdlib/number/uint64/base/add' );
var mul = require( '@stdlib/number/uint64/base/mul' );
var rightShift = require( '@stdlib/number/uint64/base/right-shift' );
var xor = require( '@stdlib/number/uint64/base/xor' );
var format = require( '@stdlib/string/format' );
var setReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' );
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setReadWriteAccessor = require( '@stdlib/utils/define-nonenumerable-read-write-accessor' );
var randuint32 = require( './rand_uint32.js' );


// VARIABLES //

// Define the LCG multiplier: 6364136223846793005 (Ref: https://github.com/imneme/pcg-c/blob/83252d9c23df9c82ecb42210afed61a7b42402d7/include/pcg_variants.h#L279)
var MULTIPLIER = [ 0x5851f42d >>> 0, 0x4c957f2d >>> 0 ]; // asm type annotation

// Define the default LCG increment: 1442695040888963407 (Ref: https://github.com/imneme/pcg-c/blob/83252d9c23df9c82ecb42210afed61a7b42402d7/include/pcg_variants.h#L284)
var DEFAULT_INCREMENT = [ 0x14057b7e >>> 0, 0xf767814f >>> 0 ]; // asm type annotation

// Define the size of the state section as a multiple of 32-bits:
var N = 2;

// Define the size of the increment section as a multiple of 32-bits:
var M = 2; // NOTE: can we reuse N here or different variable is better? pcg always has same width state and increment

// Define the maximum seed: 2^32-1 => 4294967295
var MAX_SEED = UINT32_MAX >>> 0; // asm type annotation

// Define a normalization constant when generating single-precision floating-point numbers: 1 / 2^32 => 1 / 4294967296
var NORMALIZATION_CONSTANT = 1.0 / ( UINT32_MAX+1.0 );

// Define the maximum normalized pseudorandom single-precision floating-point number: (2^32-1) / 2^32
var MAX_NORMALIZED = UINT32_MAX * NORMALIZATION_CONSTANT;

// Define the state array schema version:
var STATE_ARRAY_VERSION = 1; // NOTE: anytime the state array schema changes, this value should be incremented!!!

// Define the number of sections in the state array:
var NUM_STATE_SECTIONS = 3; // state, increment, seed

// Define the index offset of the "state" section in the state array:
var STATE_SECTION_OFFSET = 2; // | version | num_sections | state_length | ...state | increment_length | ...increment | seed_length | ...seed |

// Define the index offset of the "increment" section in the state array:
var INCREMENT_SECTION_OFFSET = 3 + N; // | version | num_sections | state_length | ...state | increment_length | ...increment | seed_length | ...seed |

// Define the index offset of the seed section in the state array:
var SEED_SECTION_OFFSET = 4 + N + M; // | version | num_sections | state_length | ...state | increment_length | ...increment | seed_length | ...seed |

// Define the length of the "fixed" length portion of the state array:
var STATE_FIXED_LENGTH = 5 + N + M; // 1 (version) + 1 (num_sections) + 1 (state_length) + N (state) + 1 (increment_length) + M (increment) + 1 (seed_length)


// FUNCTIONS //

/**
* Verifies state array integrity.
*
* @private
* @param {Uint32Array} state - state array
* @param {boolean} FLG - flag indicating whether the state array was provided as an option (true) or an argument (false)
* @returns {(Error|null)} an error or `null`
*/
function verifyState( state, FLG ) {
	var s1;
	if ( FLG ) {
		s1 = 'option';
	} else {
		s1 = 'argument';
	}
	// The state array must have a minimum length...
	if ( state.length < STATE_FIXED_LENGTH+1 ) {
		return new RangeError( format( 'invalid %s. State array has insufficient length.', s1 ) );
	}
	// The first element of the state array must equal the supported state array schema version...
	if ( state[ 0 ] !== STATE_ARRAY_VERSION ) {
		return new RangeError( format( 'invalid %s. State array has an incompatible schema version. Expected: `%s`. Actual: `%s`.', s1, STATE_ARRAY_VERSION, state[ 0 ] ) );
	}
	// The second element of the state array must contain the number of sections...
	if ( state[ 1 ] !== NUM_STATE_SECTIONS ) {
		return new RangeError( format( 'invalid %s. State array has an incompatible number of sections. Expected: `%s`. Actual: `%s`.', s1, NUM_STATE_SECTIONS, state[ 1 ] ) );
	}
	// The length of the "state" section must equal `N`...
	if ( state[ STATE_SECTION_OFFSET ] !== N ) {
		return new RangeError( format( 'invalid %s. State array has an incompatible state length. Expected: `%u`. Actual: `%u`.', s1, N, state[ STATE_SECTION_OFFSET ] ) );
	}
	// The length of the "increment" section must equal `M`...
	if ( state[ INCREMENT_SECTION_OFFSET ] !== M ) {
		return new RangeError( format( 'invalid %s. State array has an incompatible increment length. Expected: `%u`. Actual: `%u`.', s1, M, state[ INCREMENT_SECTION_OFFSET ] ) );
	}
	// The length of the "seed" section must match the empirical length...
	if ( state[ SEED_SECTION_OFFSET ] !== state.length-STATE_FIXED_LENGTH ) {
		return new RangeError( format( 'invalid %s. State array length is incompatible with seed section length. Expected: `%u`. Actual: `%u`.', s1, state.length-STATE_FIXED_LENGTH, state[ SEED_SECTION_OFFSET ] ) );
	}
	return null;
}


// MAIN //

/**
* Returns a 32-bit PCG pseudorandom number generator.
*
* @param {Options} [options] - options
* @param {PRNGSeedPCG32} [options.seed] - pseudorandom number generator seed
* @param {PRNGStatePCG32} [options.state] - pseudorandom number generator state
* @param {boolean} [options.copy=true] - boolean indicating whether to copy a provided pseudorandom number generator state
* @throws {TypeError} options argument must be an object
* @throws {TypeError} a seed must be either a nonnegative integer less than or equal to the maximum 32-bit unsigned integer or an array-like object containing integers less than or equal to the maximum 32-bit unsigned integer
* @throws {RangeError} a numeric seed must be a nonnegative integer less than or equal to the maximum 32-bit unsigned integer
* @throws {TypeError} state must be a `Uint32Array`
* @throws {Error} must provide a valid state
* @throws {TypeError} `copy` option must be a boolean
* @returns {PRNG} PCG PRNG
*
* @example
* var pcg32 = factory();
*
* var v = pcg32();
* // returns <number>
*
* @example
* // Return a seeded PCG PRNG:
* var pcg32 = factory({
*     'seed': 1234
* });
*
* var v = pcg32();
* // returns 2653504168
*/
function factory( options ) {
	var XORSHIFTED;
	var increment;
	var OLDSTATE;
	var STATE;
	var state;
	var opts;
	var seed;
	var slen;
	var err;

	// NOTE: can we merge these into the state array as OTHER SECTION or use a WORKSPACE-like array?
	XORSHIFTED = new Uint32Array( 2 );
	OLDSTATE = new Uint32Array( 2 );

	opts = {};
	if ( arguments.length ) {
		if ( !isObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
		if ( hasOwnProp( options, 'copy' ) ) {
			opts.copy = options.copy;
			if ( !isBoolean( options.copy ) ) {
				throw new TypeError( format( 'invalid option. `%s` option must be a boolean. Option: `%s`.', 'copy', options.copy ) );
			}
		}
		if ( hasOwnProp( options, 'state' ) ) {
			state = options.state;
			opts.state = true;
			if ( !isUint32Array( state ) ) {
				throw new TypeError( format( 'invalid option. `%s` option must be a Uint32Array. Option: `%s`.', 'state', state ) );
			}
			err = verifyState( state, true );
			if ( err ) {
				throw err;
			}
			if ( opts.copy === false ) {
				STATE = state;
			} else {
				STATE = new Uint32Array( state.length );
				gcopy( state.length, state, 1, STATE, 1 );
			}
		} else if ( hasOwnProp( options, 'seed' ) ) {
			// If provided a PRNG state, we ignore the `seed` option...
			seed = options.seed;
			opts.seed = true;
			if ( isNonNegativeInteger( seed ) ) {
				if ( seed > MAX_SEED ) {
					throw new RangeError( format( 'invalid option. `%s` option must be a nonnegative integer less than or equal to the maximum 32-bit unsigned integer. Option: `%u`.', 'seed', seed ) );
				}
				// Wrap inside an array for easier processing:
				seed = [ seed ];
			} else if ( !isCollection( seed ) || seed.length < 1 ) {
				throw new TypeError( format( 'invalid option. `%s` option must be either a nonnegative integer less than or equal to the maximum 32-bit unsigned integer or an array-like object containing nonnegative integer values less than or equal to the maximum 32-bit unsigned integer. Option: `%s`.', 'seed', seed ) );
			}
		}
	}

	// Create the state array if not provided a PRNG state:
	if ( !opts.state ) {
		if ( !opts.seed ) {
			// Generate a random seed if the `seed` option  or the `options` argument is not provided:
			seed = [ randuint32() ];
		}
		slen = seed.length;
		STATE = new Uint32Array( STATE_FIXED_LENGTH+slen );

		// Initialize sections:
		STATE[ 0 ] = STATE_ARRAY_VERSION;
		STATE[ 1 ] = NUM_STATE_SECTIONS;
		STATE[ STATE_SECTION_OFFSET ] = N;
		STATE[ INCREMENT_SECTION_OFFSET ] = M;
		STATE[ SEED_SECTION_OFFSET ] = slen;

		gcopy.ndarray( slen, seed, 1, 0, STATE, 1, SEED_SECTION_OFFSET+1 );
	}

	// Create a state "view":
	state = new Uint32Array( STATE.buffer, STATE.byteOffset+((STATE_SECTION_OFFSET+1)*STATE.BYTES_PER_ELEMENT), N );

	// Create an increment "view":
	increment = new Uint32Array( STATE.buffer, STATE.byteOffset+((INCREMENT_SECTION_OFFSET+1)*STATE.BYTES_PER_ELEMENT), M );

	// Create a seed "view":
	seed = new Uint32Array( STATE.buffer, STATE.byteOffset+((SEED_SECTION_OFFSET+1)*STATE.BYTES_PER_ELEMENT), 1 );

	// Initialize the internal PRNG state:
	if ( !opts.state ) {
		// Initialize the LCG increment:
		if ( slen < 3 ) {
			increment[ 0 ] = DEFAULT_INCREMENT[ 0 ];
			increment[ 1 ] = DEFAULT_INCREMENT[ 1 ];
		} else {
			if ( slen > 3 ) {
				increment[ 0 ] = seed[ 2 ];
				increment[ 1 ] = seed[ 3 ];
			} else {
				increment[ 0 ] = 0;
				increment[ 1 ] = seed[ 2 ];
			}
			// Ensure the increment is an odd number:
			// leftShift.strided( increment, 1, 0, 1, increment, 1, 0 );
			// or.assign( increment[ 0 ], increment[ 1 ], 0, 1, increment, 1, 0 );
			increment[ 0 ] = ( increment[ 0 ] << 1 ) | ( increment[ 1 ] >>> 31 );
			increment[ 1 ] = ( increment[ 1 ] << 1 ) | 1;
		}

		// Run PCG warm-up sequence:
		pcg32();
		if ( slen > 1 ) { // Use the first two elements of the seed array as the high and low 32-bit word of a 64-bit unsigned integer if the seed array length is greater than 1
			add.assign( state[ 0 ], state[ 1 ], seed[ 0 ], seed[ 1 ], state, 1, 0 );
		} else { // Otherwise use the only element as the low 32-bit word
			add.assign( state[ 0 ], state[ 1 ], 0, seed[ 0 ], state, 1, 0 );
		}
		pcg32();
	}

	// Note: property order matters in order to maintain consistency of PRNG "shape" (hidden classes).
	setReadOnly( pcg32, 'NAME', 'pcg32' );
	setReadOnlyAccessor( pcg32, 'seed', getSeed );
	setReadOnlyAccessor( pcg32, 'seedLength', getSeedLength );
	setReadWriteAccessor( pcg32, 'state', getState, setState );
	setReadOnlyAccessor( pcg32, 'stateLength', getStateLength );
	setReadOnlyAccessor( pcg32, 'byteLength', getStateSize );
	setReadOnly( pcg32, 'toJSON', toJSON );
	setReadOnly( pcg32, 'MIN', 0 );
	setReadOnly( pcg32, 'MAX', UINT32_MAX );
	setReadOnly( pcg32, 'normalized', normalized );

	setReadOnly( normalized, 'NAME', pcg32.NAME );
	setReadOnlyAccessor( normalized, 'seed', getSeed );
	setReadOnlyAccessor( normalized, 'seedLength', getSeedLength );
	setReadWriteAccessor( normalized, 'state', getState, setState );
	setReadOnlyAccessor( normalized, 'stateLength', getStateLength );
	setReadOnlyAccessor( normalized, 'byteLength', getStateSize );
	setReadOnly( normalized, 'toJSON', toJSON );
	setReadOnly( normalized, 'MIN', 0.0 );
	setReadOnly( normalized, 'MAX', MAX_NORMALIZED );

	return pcg32;

	/**
	* Returns the PRNG seed.
	*
	* @private
	* @returns {PRNGSeedPCG32} seed
	*/
	function getSeed() {
		var len = STATE[ SEED_SECTION_OFFSET ];
		return gcopy( len, seed, 1, new Uint32Array( len ), 1 );
	}

	/**
	* Returns the PRNG seed length.
	*
	* @private
	* @returns {PositiveInteger} seed length
	*/
	function getSeedLength() {
		return STATE[ SEED_SECTION_OFFSET ];
	}

	/**
	* Returns the PRNG state length.
	*
	* @private
	* @returns {PositiveInteger} state length
	*/
	function getStateLength() {
		return STATE.length;
	}

	/**
	* Returns the PRNG state size (in bytes).
	*
	* @private
	* @returns {PositiveInteger} state size (in bytes)
	*/
	function getStateSize() {
		return STATE.byteLength;
	}

	/**
	* Returns the current PRNG state.
	*
	* ## Notes
	*
	* -   The PRNG state array is comprised of a preamble followed by `3` sections:
	*
	*     0.  preamble (version + number of sections)
	*     1.  internal PRNG state
	*     2.  internal LCG increment
	*     3.  PRNG seed
	*
	* -   The first element of the PRNG state array preamble is the state array schema version.
	*
	* -   The second element of the PRNG state array preamble is the number of state array sections (i.e., `3`).
	*
	* -   The first element of each section following the preamble specifies the section length. The remaining section elements comprise the section contents.
	*
	* @private
	* @returns {PRNGStatePCG32} current state
	*/
	function getState() {
		var len = STATE.length;
		return gcopy( len, STATE, 1, new Uint32Array( len ), 1 );
	}

	/**
	* Sets the PRNG state.
	*
	* ## Notes
	*
	* -   If PRNG state is "shared" (meaning a state array was provided during PRNG creation and **not** copied) and one sets the generator state to a state array having a different length, the PRNG does **not** update the existing shared state and, instead, points to the newly provided state array. In order to synchronize PRNG output according to the new shared state array, the state array for **each** relevant PRNG must be **explicitly** set.
	* -   If PRNG state is "shared" and one sets the generator state to a state array of the same length, the PRNG state is updated (along with the state of all other PRNGs sharing the PRNG's state array).
	*
	* @private
	* @param {PRNGStatePCG32} s - generator state
	* @throws {TypeError} must provide a `Uint32Array`
	* @throws {Error} must provide a valid state
	*/
	function setState( s ) {
		var err;
		if ( !isUint32Array( s ) ) {
			throw new TypeError( format( 'invalid argument. Must provide a Uint32Array. Value: `%s`.', s ) );
		}
		err = verifyState( s, false );
		if ( err ) {
			throw err;
		}
		if ( opts.copy === false ) {
			if ( opts.state && s.length === STATE.length ) {
				gcopy( s.length, s, 1, STATE, 1 ); // update current shared state
			} else {
				STATE = s; // point to new shared state
				opts.state = true; // setting this flag allows updating a shared state even if a state array was not provided at PRNG creation
			}
		} else {
			// Check if we can reuse allocated memory...
			if ( s.length !== STATE.length ) {
				STATE = new Uint32Array( s.length ); // reallocate
			}
			gcopy( s.length, s, 1, STATE, 1 );
		}
		// Create a new state "view":
		state = new Uint32Array( STATE.buffer, STATE.byteOffset+((STATE_SECTION_OFFSET+1)*STATE.BYTES_PER_ELEMENT), N );

		// Create a new seed "view":
		seed = new Uint32Array( STATE.buffer, STATE.byteOffset+((SEED_SECTION_OFFSET+1)*STATE.BYTES_PER_ELEMENT), STATE[ SEED_SECTION_OFFSET ] );
	}

	/**
	* Serializes the pseudorandom number generator as a JSON object.
	*
	* ## Notes
	*
	* -   `JSON.stringify()` implicitly calls this method when stringifying a PRNG.
	*
	* @private
	* @returns {Object} JSON representation
	*/
	function toJSON() {
		var out = {};
		out.type = 'PRNG';
		out.name = pcg32.NAME;
		out.state = typedarray2json( STATE );
		out.params = [];
		return out;
	}

	/**
	* Generates a pseudorandom integer on the interval \\( [0, 2^{32}) \\).
	*
	* @private
	* @returns {uinteger32} pseudorandom integer
	*/
	function pcg32() {
		var rot;
		var out;

		// Update the PRNG state:
		gcopy( 2, state, 1, OLDSTATE, 1 );
		mul.strided( state, 1, 0, MULTIPLIER, 1, 0, state, 1, 0 );
		add.strided( state, 1, 0, increment, 1, 0, state, 1, 0 );

		// Apply output permutaion (XSH-RR)
		rightShift.strided( OLDSTATE, 1, 0, 18, XORSHIFTED, 1, 0 );
		xor.strided( XORSHIFTED, 1, 0, OLDSTATE, 1, 0, XORSHIFTED, 1, 0 );
		rightShift.strided( XORSHIFTED, 1, 0, 27, XORSHIFTED, 1, 0 );
		XORSHIFTED[ 0 ] = 0; // truncate to 32-bit
		rot = OLDSTATE[ 0 ] >>> 27; // extract rotate bits
		out = rotr( XORSHIFTED[ 1 ], rot );
		return out;
	}

	/**
	* Generates a pseudorandom number on the interval \\( [0, 1) \\).
	*
	* @private
	* @returns {number} pseudorandom number
	*/
	function normalized() {
		return pcg32() * NORMALIZATION_CONSTANT;
	}
}


// EXPORTS //

module.exports = factory;
